//
// It renders inside your own root route, so your header, footer, fonts and
// colours apply to it exactly as they do everywhere else on the site.
import { createFileRoute, Link } from "@tanstack/react-router";
import { getAllPosts } from "../lib/blog/posts";
import { blogStyles } from "../lib/blog/styles";

export const Route = createFileRoute("/blog/")({
  component: BlogIndexPage,
  head: () => ({
    meta: [
      { title: "Blog" },
      { name: "description", content: "Articles, guides and updates." },
    ],
    links: [{ rel: "canonical", href: "/blog" }],
  }),
});

function BlogIndexPage() {
  const posts = getAllPosts();
  return (
    <div>
      <style>{blogStyles}</style>
      <div className="sb-blog">
        <h1>Blog</h1>
        <p className="sb-blog-lede">Articles, guides and updates.</p>
        {posts.length === 0 ? (
          <p className="sb-blog-empty">No posts yet. The first one will appear here.</p>
        ) : (
          <ul className="sb-blog-list">
            {posts.map((post) => (
              <li key={post.slug} className="sb-blog-item">
                <h2>
                  <Link to={"/blog/$slug"} params={{ slug: post.slug }}>
                    {post.title}
                  </Link>
                </h2>
                {post.description ? <p>{post.description}</p> : null}
                {post.dateLabel ? (
                  <time className="sb-blog-meta" dateTime={post.date}>
                    {post.dateLabel}
                  </time>
                ) : null}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
